    with self._lock:
        return {
            k: PromptTokenUsage(
                prompt_name=v.prompt_name,
                call_count=v.call_count,
                total_input_tokens=v.total_input_tokens,
                total_output_tokens=v.total_output_tokens,
            )
            for k, v in self._usage.items()
        }

