    if status_filter == "success":
        filters.append(f"{prefix}status = 'ok'")
    elif status_filter == "error":
        filters.append(f"{prefix}status <> 'ok'")

    if tool_name:
        filters.append(f"{prefix}tool_name = :tool_name")
        params["tool_name"] = tool_name

